export const dishImageUrl = (key: string) => `/dishes/${key}.svg`;

/** Pictures whose tags appear in the item name, best match first. */
export function suggestDishImages(name: string, limit = 6): DishImage[] {
  const text = name.toLowerCase();
  if (text.trim().length < 3) return [];
  const words = text.split(/[^a-z0-9]+/).filter((w) => w.length > 2);
  return DISH_IMAGES.map((d) => ({
    d,
    score: d.tags.reduce((s, t) => s + (text.includes(t) ? t.length + 5 : words.some((w) => t.startsWith(w) || w.startsWith(t)) ? 2 : 0), 0),
  }))
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map((x) => x.d);
}
